479 |     fn create_encode_task(&mut self, arrays: Vec<ArrayRef>) -> Result<EncodeTask> {
480 |         let encoder = self
481 |             .array_encoding_strategy
482 |             .create_array_encoder(&arrays, &self.field)?;
483 |         let column_idx = self.column_index;
484 |         let data_type = self.field.data_type();
485 | 
486 |         Ok(tokio::task::spawn(async move {
487 |             let num_values = arrays.iter().map(|arr| arr.len() as u64).sum();
488 |             let data = DataBlock::from_arrays(&arrays, num_values);
489 |             let mut buffer_index = 0;
490 |             let array = encoder.encode(data, &data_type, &mut buffer_index)?;
491 |             let (data, description) = array.into_buffers();
492 |             Ok(EncodedPage {
493 |                 data,
494 |                 description: PageEncoding::Legacy(description),
495 |                 num_rows: num_values,
496 |                 column_idx,
497 |                 row_number: 0, // v2.0 encoders do not use
498 |             })
499 |         })
500 |         .map(|res_res| {
501 |             res_res.unwrap_or_else(|err| {
502 |                 Err(Error::internal(format!(
503 |                     "Encoding task failed with error: {:?}",
504 |                     err
505 |                 )))
506 |             })
507 |         })
508 |         .boxed())
509 |     }
