511 |     // Creates an encode task, consuming all buffered data
512 |     fn do_flush(&mut self, arrays: Vec<ArrayRef>) -> Result<Vec<EncodeTask>> {
513 |         DataBlock::validate_arrays(&arrays, &self.field.name)?;
514 |         if arrays.len() == 1 {
515 |             let array = arrays.into_iter().next().unwrap();
516 |             let size_bytes = array.get_buffer_memory_size();
517 |             let num_parts = bit_util::ceil(size_bytes, self.max_page_bytes as usize);
518 |             // Can't slice it finer than 1 page per row
519 |             let num_parts = num_parts.min(array.len());
520 |             if num_parts <= 1 {
521 |                 // One part and it fits in a page
522 |                 Ok(vec![self.create_encode_task(vec![array])?])
523 |             } else {
524 |                 // One part and it needs to be sliced into multiple pages
525 | 
526 |                 // This isn't perfect (items in the array might not all have the same size)
527 |                 // but it's a reasonable stab for now)
528 |                 let mut tasks = Vec::with_capacity(num_parts);
529 |                 let mut offset = 0;
530 |                 let part_size = bit_util::ceil(array.len(), num_parts);
531 |                 for _ in 0..num_parts {
532 |                     let avail = array.len() - offset;
533 |                     if avail == 0 {
534 |                         break;
535 |                     }
536 |                     let chunk_size = avail.min(part_size);
537 |                     let part = array.slice(offset, chunk_size);
538 |                     let task = self.create_encode_task(vec![part])?;
539 |                     tasks.push(task);
540 |                     offset += chunk_size;
541 |                 }
542 |                 Ok(tasks)
543 |             }
544 |         } else {
545 |             // Multiple parts that (presumably) all fit in a page
546 |             //
547 |             // TODO: Could check here if there are any jumbo parts in the mix that need splitting
548 |             Ok(vec![self.create_encode_task(arrays)?])
549 |         }
550 |     }
551 | }
