60 | impl IndicesNormalizer {
61 |     fn new(num_rows: u64, null_adjustment: u64) -> Self {
62 |         let mut indices = Vec::with_capacity(num_rows as usize);
63 |         indices.push(0);
64 |         Self {
65 |             indices,
66 |             validity: BooleanBufferBuilder::new(num_rows as usize),
67 |             null_adjustment,
68 |         }
69 |     }
70 | 
71 |     fn normalize(&self, val: u64) -> (bool, u64) {
72 |         if val >= self.null_adjustment {
73 |             (false, val - self.null_adjustment)
74 |         } else {
75 |             (true, val)
76 |         }
77 |     }
78 | 
79 |     fn extend(&mut self, new_indices: &PrimitiveArray<UInt64Type>, is_start: bool) -> Result<()> {
80 |         let mut last = *self.indices.last().unwrap();
81 |         if is_start {
82 |             let (is_valid, val) = self.normalize(new_indices.value(0));
83 |             self.indices.push(val);
84 |             self.validity.append(is_valid);
85 |             last += val;
86 |         }
87 |         let mut prev = self.normalize(*new_indices.values().first().unwrap()).1;
88 |         for (i, w) in new_indices.values().windows(2).enumerate() {
89 |             let (is_valid, val) = self.normalize(w[1]);
90 |             let next = match val.checked_sub(prev) {
91 |                 Some(delta) => delta + last,
92 |                 None => {
93 |                     return Err(lance_core::Error::invalid_input(format!(
94 |                         "corrupt binary page: normalized offset {} is less than previous offset {} \
95 |                              at index {}, null_adjustment={}, raw values were [{}, {}]. \
96 |                              This usually indicates the file data has been corrupted.",
97 |                         val, prev, i, self.null_adjustment, w[0], w[1]
98 |                     )));
99 |                 }
100 |             };
101 |             self.indices.push(next);
102 |             self.validity.append(is_valid);
103 |             prev = val;
104 |             last = next;
105 |         }
106 |         Ok(())
107 |     }
108 | 
109 |     fn into_parts(mut self) -> (Vec<u64>, BooleanBuffer) {
110 |         (self.indices, self.validity.finish())
111 |     }
112 | }
