447 | // Strings are a vector of arrays corresponding to each record batch
448 | // Zero offset is removed from the start of the offsets array
449 | // The indices array is computed across all arrays in the vector
450 | fn get_indices_from_string_arrays(
451 |     offsets: LanceBuffer,
452 |     bits_per_offset: u8,
453 |     nulls: Option<LanceBuffer>,
454 |     num_rows: usize,
455 | ) -> (DataBlock, u64) {
456 |     let mut indices = Vec::with_capacity(num_rows);
457 |     let mut last_offset = 0_u64;
458 |     if bits_per_offset == 32 {
459 |         let offsets = offsets.borrow_to_typed_slice::<i32>();
460 |         indices.extend(offsets.as_ref().windows(2).map(|w| {
461 |             let strlen = (w[1] - w[0]) as u64;
462 |             last_offset += strlen;
463 |             last_offset
464 |         }));
465 |     } else if bits_per_offset == 64 {
466 |         let offsets = offsets.borrow_to_typed_slice::<i64>();
467 |         indices.extend(offsets.as_ref().windows(2).map(|w| {
468 |             let strlen = (w[1] - w[0]) as u64;
469 |             last_offset += strlen;
470 |             last_offset
471 |         }));
472 |     }
473 | 
474 |     if indices.is_empty() {
475 |         return (
476 |             DataBlock::FixedWidth(FixedWidthDataBlock {
477 |                 bits_per_value: 64,
478 |                 data: LanceBuffer::empty(),
479 |                 num_values: 0,
480 |                 block_info: BlockInfo::new(),
481 |             }),
482 |             0,
483 |         );
484 |     }
485 | 
486 |     let last_offset = *indices.last().expect("Indices array is empty");
487 |     // 8 exabytes in a single array seems unlikely but...just in case
488 |     assert!(
489 |         last_offset < u64::MAX / 2,
490 |         "Indices array with strings up to 2^63 is too large for this encoding"
491 |     );
492 |     let null_adjustment: u64 = *indices.last().expect("Indices array is empty") + 1;
493 | 
494 |     if let Some(nulls) = nulls {
495 |         let nulls = NullBuffer::new(BooleanBuffer::new(nulls.into_buffer(), 0, num_rows));
496 |         indices
497 |             .iter_mut()
498 |             .zip(nulls.iter())
499 |             .for_each(|(index, is_valid)| {
500 |                 if !is_valid {
501 |                     *index += null_adjustment;
502 |                 }
503 |             });
504 |     }
505 |     let indices = DataBlock::FixedWidth(FixedWidthDataBlock {
506 |         bits_per_value: 64,
507 |         data: LanceBuffer::reinterpret_vec(indices),
508 |         num_values: num_rows as u64,
509 |         block_info: BlockInfo::new(),
510 |     });
511 |     (indices, null_adjustment)
512 | }
