514 | impl ArrayEncoder for BinaryEncoder {
515 |     fn encode(
516 |         &self,
517 |         data: DataBlock,
518 |         data_type: &DataType,
519 |         buffer_index: &mut u32,
520 |     ) -> Result<EncodedArray> {
521 |         let (mut data, nulls) = match data {
522 |             DataBlock::Nullable(nullable) => {
523 |                 let data = nullable.data.as_variable_width().unwrap();
524 |                 (data, Some(nullable.nulls))
525 |             }
526 |             DataBlock::VariableWidth(variable) => (variable, None),
527 |             DataBlock::AllNull(all_null) => {
528 |                 let data = Self::all_null_variable_width(data_type, all_null.num_values);
529 |                 let validity =
530 |                     LanceBuffer::all_unset(bit_util::ceil(all_null.num_values as usize, 8));
531 |                 (data, Some(validity))
532 |             }
533 |             _ => panic!("Expected variable width data block but got {}", data.name()),
534 |         };
535 | 
536 |         let (indices, null_adjustment) = get_indices_from_string_arrays(
537 |             data.offsets,
538 |             data.bits_per_offset,
539 |             nulls,
540 |             data.num_values as usize,
541 |         );
542 |         let encoded_indices =
543 |             self.indices_encoder
544 |                 .encode(indices, &DataType::UInt64, buffer_index)?;
545 | 
546 |         let encoded_indices_data = encoded_indices.data.as_fixed_width().unwrap();
547 | 
548 |         assert!(encoded_indices_data.bits_per_value <= 64);
549 | 
550 |         if let Some(buffer_compressor) = &self.buffer_compressor {
551 |             let mut compressed_data = Vec::with_capacity(data.data.len());
552 |             buffer_compressor.compress(&data.data, &mut compressed_data)?;
553 |             data.data = LanceBuffer::from(compressed_data);
554 |         }
555 | 
556 |         let data = DataBlock::VariableWidth(VariableWidthBlock {
557 |             bits_per_offset: encoded_indices_data.bits_per_value as u8,
558 |             offsets: encoded_indices_data.data,
559 |             data: data.data,
560 |             num_values: data.num_values,
561 |             block_info: BlockInfo::new(),
562 |         });
563 | 
564 |         let bytes_buffer_index = *buffer_index;
565 |         *buffer_index += 1;
566 | 
567 |         let bytes_encoding = ProtobufUtils::flat_encoding(
568 |             /*bits_per_value=*/ 8,
569 |             bytes_buffer_index,
570 |             self.compression_config,
571 |         );
572 | 
573 |         let encoding =
574 |             ProtobufUtils::binary(encoded_indices.encoding, bytes_encoding, null_adjustment);
575 | 
576 |         Ok(EncodedArray { data, encoding })
577 |     }
578 | }
